class TokenBucket:
    def __init__(self, capacity, refill_per_sec, clock):
        if capacity <= 0:
            raise ValueError("capacity must be a positive number")
        if refill_per_sec < 0:
            raise ValueError("refill_per_sec must be a non-negative number")

        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.tokens = capacity
        self.last_refill = clock.now()

    def allow(self, cost=1):
        if cost <= 0:
            raise ValueError("cost must be a positive number")

        now = self.clock.now()
        elapsed = now - self.last_refill
        self.tokens += elapsed * self.refill_per_sec
        self.tokens = min(self.tokens, self.capacity)
        self.last_refill = now

        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False

class RateLimiter:
    def __init__(self, capacity, refill_per_sec, clock):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.buckets = {}

    def check(self, client, cost=1):
        if client not in self.buckets:
            self.buckets[client] = TokenBucket(self.capacity, self.refill_per_sec, self.clock)
        return self.buckets[client].allow(cost)
