from gwlib.router import Router
from gwlib.metrics import Metrics
from gwlib.request import Request
from gwlib.response import Response
from gwlib.ratelimit import RateLimiter

class Gateway:
    def __init__(self, router, metrics, clock, limiter=None):
        self.router = router
        self.metrics = metrics
        self.clock = clock
        self.limiter = limiter

    def dispatch(self, request):
        route = self.router.resolve(request)
        self.metrics.increment(f"route.{route.name}.calls")

        if self.limiter and not self.limiter.check(request.client):
            self.metrics.increment("route.limited")
            return Response(429, "rate limited")

        try:
            handler = route.handler
            result = handler(request)
            self.metrics.increment(f"route.{route.name}.ok")
            return result
        except Exception as e:
            self.metrics.increment(f"route.{route.name}.error")
            return Response(500, str(e))
        except KeyError:
            self.metrics.increment(f"route.{route.name}.unknown")
            return Response(404, "unknown route")
